package com.smartmerchant.saas.iam.interfaces;
import com.smartmerchant.saas.iam.application.AuthService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth/v1") public class AuthController { private final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/login") public Object login(@Valid @RequestBody LoginRequest r,HttpServletRequest req){try{return service.login(r.username(),r.password(),req.getRemoteAddr());}catch(IllegalArgumentException e){throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"账号或密码错误");}} @PostMapping("/refresh") public Object refresh(@Valid @RequestBody TokenRequest r){return service.refresh(r.refreshToken());} @PostMapping("/logout") public Map<String,String> logout(@Valid @RequestBody TokenRequest r){service.logout(r.refreshToken());return Map.of("status","LOGGED_OUT");} public record LoginRequest(@NotBlank String username,@NotBlank String password){} public record TokenRequest(@NotBlank String refreshToken){} }
